var cl = localStorage.getItem('qs-lang') || 'zh';
var _helpI18nLoaded = false;
var _helpI18nLoading = false;
var _helpI18nCallbacks = [];

// v4.2: Lazy-load help i18n dictionary on first use
function loadHelpI18n(cb) {
  if (_helpI18nLoaded) { if (cb) cb(); return; }
  if (cb) _helpI18nCallbacks.push(cb);
  if (_helpI18nLoading) return;
  _helpI18nLoading = true;
  var s = document.createElement('script');
  s.src = 'i18n-help.js?v=c20354';
  s.onload = function() {
    _helpI18nLoaded = true;
    _helpI18nLoading = false;
    // Merge help keys into I18N so t() finds them
    for (var lang in I18N_HELP) {
      if (!I18N[lang]) continue;
      for (var k in I18N_HELP[lang]) {
        if (!I18N[lang][k]) I18N[lang][k] = I18N_HELP[lang][k];
      }
    }
    var q = _helpI18nCallbacks; _helpI18nCallbacks = [];
    for (var i = 0; i < q.length; i++) { try { q[i](); } catch(e) {} }
    // Refresh UI for any help panels currently visible
    if (typeof applyLanguage === 'function') applyLanguage(cl);
  };
  s.onerror = function() { _helpI18nLoading = false; _helpI18nCallbacks = []; };
  document.head.appendChild(s);
}

function t(k, v) {
  var s = (I18N[cl] && I18N[cl][k]) || I18N['en'][k] || k;
  if (v) for (var vk in v) s = s.replace('{' + vk + '}', v[vk]);
  return s;
}

function applyLanguage(lang) {
  cl = lang;
  localStorage.setItem('qs-lang', lang);
  document.documentElement.lang = lang;
  // data-i18n-html-only elements (e.g. #epicenter-info) were never selected
  // by the old '[data-i18n]' query and kept their hardcoded English at boot.
  var els = document.querySelectorAll('[data-i18n],[data-i18n-html]');
  for (var i = 0; i < els.length; i++) {
    var el = els[i], key = el.getAttribute('data-i18n') || el.getAttribute('data-i18n-html');
    if (!key) continue;
    // Support data-i18n-vars for {placeholder} substitution
    var vars = el.getAttribute('data-i18n-vars');
    var varObj = null;
    if (vars) {
      varObj = {};
      var vk = vars.split(',');
      for (var vi = 0; vi < vk.length; vi++) {
        var kn = vk[vi].trim();
        varObj[kn] = el.getAttribute('data-' + kn) || el.textContent || '';
      }
    }
    if (el.hasAttribute('data-i18n-html')) el.innerHTML = t(key, varObj);
    else el.textContent = t(key, varObj);
  }
  // Translate aria-labels on icon-only controls (data-i18n-aria="key").
  var ars = document.querySelectorAll('[data-i18n-aria]');
  for (var j = 0; j < ars.length; j++) {
    var akey = ars[j].getAttribute('data-i18n-aria');
    if (akey) ars[j].setAttribute('aria-label', t(akey));
  }
  // Translate placeholders (data-i18n-ph="key").
  var phs = document.querySelectorAll('[data-i18n-ph]');
  for (var p = 0; p < phs.length; p++) {
    var pkey = phs[p].getAttribute('data-i18n-ph');
    if (pkey) phs[p].setAttribute('placeholder', t(pkey));
  }
  // Translate hover tooltips (data-i18n-title="key").
  var tts = document.querySelectorAll('[data-i18n-title]');
  for (var q = 0; q < tts.length; q++) {
    var tkey = tts[q].getAttribute('data-i18n-title');
    if (tkey) tts[q].setAttribute('title', t(tkey));
  }
  var sel = document.getElementById('lang-select');
  if (sel && sel.value !== lang) sel.value = lang;
  if (typeof refreshDynamicUI === 'function') refreshDynamicUI();
  if (typeof rebuildLayerControl === 'function') rebuildLayerControl();
}
